(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.016-t*0.28)*18 + Math.sin(x*0.014+t*0.32)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const w2x = Math.sin(y*0.025+t*0.5)*6 + Math.cos(x*0.02-t*0.4)*5;
  const w2y = Math.cos(x*0.022-t*0.45)*6 + Math.sin(y*0.018+t*0.55)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1.2],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 5.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.45+2)*50, 0.11, 2.1, 4.2],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*70, 0.085, 1.8, 2.8],
    [200+Math.sin(t*0.42+6)*90, 220+Math.cos(t*0.58+1)*40, 0.075, 2.4, 1.5],
    [300+Math.cos(t*0.48+2)*80, 100+Math.sin(t*0.62+5)*60, 0.095, 2.0, 3.5]
  ];
  let aS=0, iS=0, dS=0;
  for(const [sX,sY,f,sp,ph] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5);
    dS+=Math.sin(d*f*0.4-t*sp*0.3+ph*0.5)*Math.cos(d*f*0.15+t*sp*0.15);
  }
  const act=aS/10, inh=iS/10, diff=dS/10;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.8)+Math.sin(sx*0.028-sy*0.038+t*1.1))/2
    +Math.sin((sx+sy)*0.1+t*2.5)*0.2+Math.sin((sx-sy)*0.085-t*2)*0.2
    +Math.sin(sx*0.06+t*1.8)*Math.cos(sy*0.055-t*1.4)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3-t*1.5)+Math.sin(dist*0.035+ang*4-t*1.2))*0.35
    +Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const pulse=Math.sin(dist*0.03-t*1.8)*Math.exp(-dist*0.003)*0.4;
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral+diff*0.4+pulse)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.5
    +Math.sin(sx*0.07-t*0.8)*Math.cos(sy*0.11+t*0.6)*0.3)*1.4)*0.25;
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.25-t*2.5)*0.08;
  const blend=reaction*0.65+cell*0.2+micro, v=blend*0.5+0.5;
  const hueShift=Math.sin(t*0.15)*0.08+Math.sin(dist*0.008-t*0.3)*0.06;
  const pal=[
    [12,22,82],[18,55,120],[20,95,130],[25,140,135],[45,170,120],
    [140,190,80],[210,185,55],[220,140,65],[200,95,70],[170,55,70],
    [120,35,75],[70,22,65],[30,18,72],[12,22,82]
  ];
  const shiftIdx=hueShift*(pal.length-1);
  let adj=v*(pal.length-1)+shiftIdx;
  adj=adj<0?adj+(pal.length-1):adj>pal.length-1?adj-(pal.length-1):adj;
  const i=Math.min(Math.abs(adj)|0,pal.length-2), f=adj-Math.floor(adj);
  const ni=(i+1)%pal.length;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18+Math.abs(diff)*0.05;
  const edge=Math.abs(reaction)>0.65?1.12:Math.abs(reaction)>0.4?1.04:0.95;
  const vig=1-Math.sqrt((x-cx)**2+(y-cy)**2)*0.0008;
  const glow=Math.max(0,reaction-0.3)*0.5;
  const r=(pal[i][0]+(pal[ni][0]-pal[i][0])*f)*lum*edge*vig+glow*40;
  const g=(pal[i][1]+(pal[ni][1]-pal[i][1])*f)*lum*edge*vig+glow*25;
  const b=(pal[i][2]+(pal[ni][2]-pal[i][2])*f)*lum*edge*vig+glow*15;
  return [Math.min(255,Math.max(0,r))|0, Math.min(255,Math.max(0,g))|0, Math.min(255,Math.max(0,b))|0];
}
